//! Compare paired measurements with animated two-period slope lines.
use crate::primitives::{
    family::{Paint, PhaseClock, Slide, disabled_motion},
    glyph::{Glyph, icon, transformed},
    presentation::{column, in_out, title, tr},
};
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};

/// The story item is drawn in the shared first-series hue.
const HIGHLIGHT: u32 = 0x55adff;
/// Heading row above the plot.
const HEAD: f32 = 28.;
/// Vertical padding kept so dots never touch the plot edges.
const PAD: f32 = 14.;
/// Minimum centre distance between two spread labels.
const LABEL_GAP: f32 = 20.;
/// Pointer distance at which a line or label is still read.
const NEAR: f32 = 22.;
/// Visual settle time when a dataset switch morphs lines and labels.
const MORPH_SECONDS: f32 = 0.46;
/// Tooltip glide time between lines in focus.
const TIP_SECONDS: f32 = 0.26;
/// Tooltip fade-out time once nothing is in focus.
const TIP_FADE: f32 = 0.16;
/// Estimated tooltip box used to keep it inside the chart.
const TIP_W: f32 = 180.;
const TIP_H: f32 = 104.;

/// A stable series measured across exactly two periods.
///
/// The key keeps a line stable across datasets, so switching data morphs it.
#[derive(Clone, Debug)]
pub struct SlopeSeries {
    pub id: SharedString,
    pub label: SharedString,
    pub before: f32,
    pub after: f32,
}
impl SlopeSeries {
    pub fn new(
        id: impl Into<SharedString>,
        label: impl Into<SharedString>,
        before: f32,
        after: f32,
    ) -> Self {
        Self {
            id: id.into(),
            label: label.into(),
            before: if before.is_finite() { before } else { 0. },
            after: if after.is_finite() { after } else { 0. },
        }
    }
}
/// A series entered focus, by pointer, touch or keyboard.
#[derive(Clone, Debug)]
pub struct SlopeInspect {
    pub id: SharedString,
    pub before: f32,
    pub after: f32,
}
struct SlopeVisual {
    id: SharedString,
    before: Slide,
    after: Slide,
    /// Rank move beside the end value: "=" or the moved places.
    rank: SharedString,
    /// The text rolling out while the new one rolls in.
    prev_rank: SharedString,
    /// Restarted when the rank text changes.
    roll: PhaseClock,
    /// A rise or level move rolls in from below; a fall rolls in from above.
    roll_from_below: bool,
}
impl SlopeVisual {
    fn roll_p(&self, cx: &App) -> f32 {
        (self.roll.age(cx) / 0.26).clamp(0., 1.)
    }
}
/// A before-and-after slope chart with a focus item, rank moves and a gliding tooltip.
pub struct SlopeChart {
    label: SharedString,
    meta: Option<SharedString>,
    start_label: SharedString,
    end_label: SharedString,
    series: Vec<SlopeSeries>,
    visual: Vec<SlopeVisual>,
    active: Option<usize>,
    highlight: Option<SharedString>,
    ranks: bool,
    value_prefix: SharedString,
    value_suffix: SharedString,
    row_height: f32,
    empty_label: SharedString,
    bounds: Rc<Cell<Bounds<Pixels>>>,
    initialized: bool,
    draw: PhaseClock,
    revealed: bool,
    visible: bool,
    touching: Rc<Cell<bool>>,
    tip_x: Slide,
    tip_y: Slide,
    /// The row whose content the tooltip keeps while it fades out.
    tip_shown: Option<usize>,
    /// Restarted when the fade-out begins.
    tip_fade: PhaseClock,
    tip_fade_on: bool,
}
impl EventEmitter<SlopeInspect> for SlopeChart {}
impl SlopeChart {
    pub fn new(label: impl Into<SharedString>, series: Vec<SlopeSeries>) -> Self {
        Self {
            label: label.into(),
            meta: None,
            start_label: "Before".into(),
            end_label: "After".into(),
            series,
            visual: vec![],
            active: None,
            highlight: None,
            ranks: true,
            value_prefix: "".into(),
            value_suffix: "".into(),
            row_height: 44.,
            empty_label: "No data".into(),
            bounds: Default::default(),
            initialized: false,
            draw: PhaseClock::default(),
            revealed: false,
            visible: true,
            touching: Default::default(),
            tip_x: Slide::new(0.),
            tip_y: Slide::new(0.),
            tip_shown: None,
            tip_fade: PhaseClock::default(),
            tip_fade_on: false,
        }
    }
    /// Secondary line under the heading.
    pub fn with_meta(mut self, meta: impl Into<SharedString>) -> Self {
        self.meta = Some(meta.into());
        self
    }
    /// Heading of the first column, such as "Q1".
    pub fn with_start_label(mut self, label: impl Into<SharedString>) -> Self {
        self.start_label = label.into();
        self
    }
    /// Heading of the second column, such as "Q2".
    pub fn with_end_label(mut self, label: impl Into<SharedString>) -> Self {
        self.end_label = label.into();
        self
    }
    /// The item drawn in the shared first-series hue.
    pub fn with_highlight(mut self, id: impl Into<SharedString>) -> Self {
        self.highlight = Some(id.into());
        self
    }
    /// Rank movement beside each end value. Defaults to shown.
    pub fn with_ranks(mut self, ranks: bool) -> Self {
        self.ranks = ranks;
        self
    }
    /// Text placed before every formatted value, such as "$".
    pub fn with_value_prefix(mut self, prefix: impl Into<SharedString>) -> Self {
        self.value_prefix = prefix.into();
        self
    }
    /// Text placed after every formatted value, such as "%".
    pub fn with_value_suffix(mut self, suffix: impl Into<SharedString>) -> Self {
        self.value_suffix = suffix.into();
        self
    }
    /// Plot height in pixels per item. Defaults to 44.
    pub fn with_row_height(mut self, row_height: f32) -> Self {
        self.row_height = row_height.max(20.);
        self
    }
    /// Message shown when there are no items.
    pub fn with_empty_label(mut self, label: impl Into<SharedString>) -> Self {
        self.empty_label = label.into();
        self
    }
    /// The host sets this to false when the chart or its tab is hidden.
    pub fn set_visible(&mut self, visible: bool, cx: &mut Context<Self>) {
        if self.visible != visible {
            self.visible = visible;
            cx.notify();
        }
    }
    /// Switch datasets; matched keys morph their lines, dots and labels.
    pub fn set_series(&mut self, series: Vec<SlopeSeries>, cx: &mut Context<Self>) {
        let kept = self
            .active
            .and_then(|i| self.visual.get(i))
            .map(|v| v.id.clone());
        self.series = series;
        self.active = kept.and_then(|id| {
            self.series
                .iter()
                .position(|s| s.id == id)
                .filter(|&i| self.series.get(i).is_some())
        });
        let old = std::mem::take(&mut self.visual);
        let mut old: Vec<Option<SlopeVisual>> = old.into_iter().map(Some).collect();
        self.visual = self
            .series
            .iter()
            .map(|s| {
                let index = old
                    .iter()
                    .position(|x| x.as_ref().is_some_and(|x| x.id == s.id));
                let mut state = index
                    .and_then(|i| old[i].take())
                    .unwrap_or_else(|| SlopeVisual {
                        id: s.id.clone(),
                        before: Slide::new(s.before),
                        after: Slide::new(s.before),
                        rank: rank_move_text(&self.series, s),
                        prev_rank: "".into(),
                        roll: PhaseClock::default(),
                        roll_from_below: true,
                    });
                state.before.duration(s.before, MORPH_SECONDS, cx);
                state.after.duration(s.after, MORPH_SECONDS, cx);
                let text = rank_move_text(&self.series, s);
                if state.rank.is_empty() {
                    state.rank = text;
                } else if state.rank != text {
                    state.prev_rank = state.rank.clone();
                    state.rank = text;
                    state.roll.restart(cx);
                    state.roll_from_below = rank_move(&self.series, &s.id) >= 0;
                }
                state
            })
            .collect();
        self.initialized = true;
        cx.notify();
    }
    fn inspect(&mut self, next: Option<usize>, cx: &mut Context<Self>) {
        if self.active == next {
            return;
        }
        self.active = next;
        if let Some(item) = next.and_then(|i| self.series.get(i)) {
            cx.emit(SlopeInspect {
                id: item.id.clone(),
                before: item.before,
                after: item.after,
            });
        }
        cx.notify();
    }
}
/// Rank in a column: 1 for the largest value; ties share a rank.
fn rank_of(series: &[SlopeSeries], field: fn(&SlopeSeries) -> f32, id: &SharedString) -> usize {
    let own = series.iter().find(|s| &s.id == id).map(field).unwrap_or(0.);
    series.iter().filter(|s| field(s) > own).count() + 1
}
/// Positive when the item moved up between the two periods.
fn rank_move(series: &[SlopeSeries], id: &SharedString) -> isize {
    let before = rank_of(series, |s| s.before, id);
    let after = rank_of(series, |s| s.after, id);
    before as isize - after as isize
}
fn rank_move_text(series: &[SlopeSeries], item: &SlopeSeries) -> SharedString {
    let move_places = rank_move(series, &item.id);
    if move_places == 0 {
        "=".into()
    } else {
        format!("{}", move_places.abs()).into()
    }
}
/// Items in end-value order, largest first.
fn end_order(series: &[SlopeSeries]) -> Vec<usize> {
    let mut order: Vec<usize> = (0..series.len()).collect();
    order.sort_by(|&a, &b| series[b].after.total_cmp(&series[a].after));
    order
}
/// One decimal at most, trailing zero dropped: 4.0 → "4", 3.1 → "3.1".
fn grouped1(value: f32) -> String {
    let text = format!("{:.1}", value);
    text.strip_suffix(".0").unwrap_or(&text).to_string()
}
/// Reference change format: "+" or a true minus sign, then the difference.
fn change_text(diff: f32, prefix: &str, suffix: &str) -> String {
    let sign = if diff >= 0. { "+" } else { "\u{2212}" };
    format!("{sign}{prefix}{}{suffix}", grouped1(diff.abs()))
}
fn value_text(value: f32, prefix: &str, suffix: &str) -> String {
    format!("{prefix}{}{suffix}", grouped1(value))
}
fn rank_line(r0: usize, r1: usize) -> String {
    if r0 == r1 {
        "same rank".to_string()
    } else if r1 < r0 {
        format!("up {} to rank {}", r0 - r1, r1)
    } else {
        format!("down {} to rank {}", r1 - r0, r1)
    }
}
/// Moves labels apart just enough: touching labels form one group centred on
/// where its members want to be, clamped to the plot.
fn spread_labels(wanted: &[f32], height: f32) -> Vec<f32> {
    let gap = LABEL_GAP;
    let low = 8.;
    let high = (height - 8.).max(low);
    let mut order: Vec<usize> = (0..wanted.len()).collect();
    order.sort_by(|&a, &b| wanted[a].total_cmp(&wanted[b]));
    let mut groups: Vec<(Vec<usize>, f32)> = order.iter().map(|&i| (vec![i], wanted[i])).collect();
    let mut changed = true;
    while changed {
        changed = false;
        let mut next: Vec<(Vec<usize>, f32)> = Vec::new();
        for group in groups {
            if let Some(prev) = next
                .last_mut()
                .filter(|prev| prev.1 + prev.0.len() as f32 * gap > group.1)
            {
                let members = prev
                    .0
                    .iter()
                    .chain(group.0.iter())
                    .copied()
                    .collect::<Vec<_>>();
                let top = members
                    .iter()
                    .enumerate()
                    .map(|(k, &i)| wanted[i] - k as f32 * gap)
                    .sum::<f32>()
                    / members.len() as f32;
                *prev = (members, top);
                changed = true;
                continue;
            }
            next.push(group);
        }
        for group in next.iter_mut() {
            group.1 = group
                .1
                .clamp(low, (high - (group.0.len() - 1) as f32 * gap).max(low));
        }
        groups = next;
    }
    let mut out = vec![0.; wanted.len()];
    for group in &groups {
        for (k, &i) in group.0.iter().enumerate() {
            out[i] = group.1 + k as f32 * gap;
        }
    }
    out
}
/// The tooltip anchor: the line's middle, kept above when it fits, inside otherwise.
fn tip_anchor(mid: f32, plot_height: f32, width: f32, x0: f32, x1: f32) -> (f32, f32) {
    let above = mid - TIP_H - 16. >= 0.;
    let left = ((x0 + x1) * 0.5 - TIP_W * 0.5).clamp(0., (width - TIP_W).max(0.));
    let top = (HEAD + if above { mid - TIP_H - 16. } else { mid + 16. })
        .clamp(0., (HEAD + plot_height - TIP_H).max(0.));
    (left, top)
}
/// The row nearest the pointer: along the line inside the plot, or beside its label.
fn nearest_series(
    b: Bounds<Pixels>,
    pos: Point<Pixels>,
    rows: &[(f32, f32)],
    l0: &[f32],
    l1: &[f32],
    x0: f32,
    x1: f32,
) -> Option<usize> {
    let width = f32::from(b.size.width).max(1.);
    let height = f32::from(b.size.height).max(1.);
    let x = f32::from(pos.x - b.origin.x);
    let y = f32::from(pos.y - b.origin.y);
    if x < 0. || x > width || y < -4. || y > height + 4. {
        return None;
    }
    let t = ((x - x0) / (x1 - x0).max(1.)).clamp(0., 1.);
    rows.iter()
        .enumerate()
        .map(|(i, (a, z))| {
            let on_line = (a + (z - a) * t - y).abs();
            let on_label = if x < x0 {
                (l0.get(i).copied().unwrap_or(0.) - y).abs()
            } else if x > x1 {
                (l1.get(i).copied().unwrap_or(0.) - y).abs()
            } else {
                f32::INFINITY
            };
            (i, on_line.min(on_label))
        })
        .min_by(|a, b| a.1.total_cmp(&b.1))
        .filter(|(_, d)| *d <= NEAR)
        .map(|(i, _)| i)
}
fn intersects_viewport(b: Bounds<Pixels>, viewport: Size<Pixels>) -> bool {
    b.size.width > px(0.)
        && b.size.height > px(0.)
        && b.origin.x < viewport.width
        && b.origin.y < viewport.height
        && b.origin.x + b.size.width > px(0.)
        && b.origin.y + b.size.height > px(0.)
}
/// Left and right label room; the rank column releases width when hidden.
fn gutters(width: f32, ranks: bool) -> (f32, f32) {
    let narrow = width < 440.;
    let left = if !narrow {
        168.
    } else if width < 300. {
        116.
    } else {
        132.
    };
    let right = if ranks {
        if narrow { 76. } else { 96. }
    } else if narrow {
        52.
    } else {
        64.
    };
    (left, right)
}
/// Axis coordinates from the label rooms: x0 sits at the left room, x1 that
/// far from the right edge, never closer than 40px to x0.
fn axes(width: f32, ranks: bool) -> (f32, f32) {
    let (left, right) = gutters(width, ranks);
    (left, (width - right).max(left + 40.))
}
impl SlopeChart {
    fn value_span(&self) -> (f32, f32) {
        let mut lo = f32::INFINITY;
        let mut hi = f32::NEG_INFINITY;
        for s in &self.series {
            lo = lo.min(s.before).min(s.after);
            hi = hi.max(s.before).max(s.after);
        }
        if !lo.is_finite() || !hi.is_finite() {
            return (0., 1.);
        }
        if hi - lo < 1e-9 {
            return (lo - 1., hi + 1.);
        }
        (lo, hi)
    }
}
fn highlight_color() -> Hsla {
    rgb(HIGHLIGHT).into()
}
impl Render for SlopeChart {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let empty = self.series.is_empty();
        let plot_height = (self.series.len() as f32 * self.row_height).max(200.);
        if !self.initialized {
            self.initialized = true;
            self.visual = self
                .series
                .iter()
                .map(|s| SlopeVisual {
                    id: s.id.clone(),
                    before: Slide::new(s.before),
                    after: Slide::new(s.after),
                    rank: rank_move_text(&self.series, s),
                    prev_rank: "".into(),
                    roll: PhaseClock::default(),
                    roll_from_below: true,
                })
                .collect();
        }
        let measured = self.bounds.get();
        let on_screen =
            self.visible && w.is_visible() && intersects_viewport(measured, w.viewport_size());
        if on_screen && !self.revealed {
            self.revealed = true;
            self.draw.restart(cx);
        }
        let now = cx.background_executor().now();
        let reduced = disabled_motion(cx);
        let age = if reduced {
            100.
        } else if self.revealed {
            self.draw.age(cx)
        } else {
            0.
        };
        let line_done = 0.1 + self.series.len().saturating_sub(1) as f32 * 0.05 + 0.7;
        let mut moving = false;
        let p = Paint::get(cx);
        let mut values: Vec<(f32, f32)> = Vec::with_capacity(self.visual.len());
        for v in &self.visual {
            let (before, a) = v.before.sample_batch(now, reduced);
            let (after, b) = v.after.sample_batch(now, reduced);
            moving |= a || b;
            values.push((before, after));
        }
        for v in &self.visual {
            moving |= v.roll.age(cx) < 0.3;
        }
        let width = if measured.size.width > px(0.) {
            f32::from(measured.size.width)
        } else {
            720.
        };
        let (x0, x1) = axes(width, self.ranks);
        let (lo, hi) = self.value_span();
        let span = (hi - lo).max(1e-9);
        let y_of = |v: f32| PAD + (1. - (v - lo) / span) * (plot_height - PAD * 2.);
        let l0 = spread_labels(
            &values.iter().map(|(v, _)| y_of(*v)).collect::<Vec<_>>(),
            plot_height,
        );
        let l1 = spread_labels(
            &values.iter().map(|(_, v)| y_of(*v)).collect::<Vec<_>>(),
            plot_height,
        );
        let rows: Vec<(f32, f32)> = values.iter().map(|(a, z)| (y_of(*a), y_of(*z))).collect();
        let by_end = end_order(&self.series);
        let active = self.active;
        let highlight = self.highlight.clone();
        let prefix = self.value_prefix.to_string();
        let suffix = self.value_suffix.to_string();
        let accent_flags: Vec<bool> = self
            .series
            .iter()
            .map(|s| highlight.as_ref().is_some_and(|h| h == &s.id))
            .collect();
        // Tooltip: glide to the line in focus, keep content while fading out.
        let tip_fading = self.tip_shown.is_some() && active.is_none();
        let tip_opacity = if tip_fading {
            if !self.tip_fade_on {
                self.tip_fade_on = true;
                self.tip_fade.restart(cx);
            }
            (1. - self.tip_fade.age(cx) / TIP_FADE).clamp(0., 1.)
        } else {
            1.
        };
        if tip_fading {
            let fade_age = self.tip_fade.age(cx);
            moving |= fade_age < TIP_FADE + 0.05;
            if fade_age > TIP_FADE {
                self.tip_shown = None;
                self.tip_fade_on = false;
            }
        }
        if let Some(i) = active {
            let mid = (rows[i].0 + rows[i].1) * 0.5;
            let (left, top) = tip_anchor(mid, plot_height, width, x0, x1);
            if self.tip_shown != Some(i) && self.tip_shown.is_none() {
                self.tip_x.reset(left);
                self.tip_y.reset(top);
            } else {
                self.tip_x.duration(left, TIP_SECONDS, cx);
                self.tip_y.duration(top, TIP_SECONDS, cx);
            }
            self.tip_shown = Some(i);
            self.tip_fade_on = false;
        }
        let (tip_left, tip_moving_x) = self.tip_x.sample_batch(now, reduced);
        let (tip_top, tip_moving_y) = self.tip_y.sample_batch(now, reduced);
        moving |= tip_moving_x || tip_moving_y;
        if on_screen && (moving || (!reduced && self.revealed && age < line_done + 0.9)) {
            w.request_animation_frame();
        }
        // Readings for assistive technology.
        let announce = active
            .and_then(|i| self.series.get(i))
            .map(|s| {
                let r0 = rank_of(&self.series, |x| x.before, &s.id);
                let r1 = rank_of(&self.series, |x| x.after, &s.id);
                format!(
                    "{}, {} {}, {} {}, {}, {}",
                    s.label,
                    self.start_label,
                    value_text(s.before, &prefix, &suffix),
                    self.end_label,
                    value_text(s.after, &prefix, &suffix),
                    change_text(s.after - s.before, &prefix, &suffix),
                    rank_line(r0, r1),
                )
            })
            .unwrap_or_default();
        let summary = if empty {
            format!("{}. {}.", self.label, self.empty_label)
        } else {
            let items = by_end
                .iter()
                .filter_map(|&i| self.series.get(i))
                .map(|s| {
                    format!(
                        "{} {} to {}",
                        s.label,
                        value_text(s.before, &prefix, &suffix),
                        value_text(s.after, &prefix, &suffix)
                    )
                })
                .collect::<Vec<_>>()
                .join(", ");
            format!(
                "{}. {} to {}. {items}.",
                self.label, self.start_label, self.end_label
            )
        };
        let table_rows: Vec<String> = by_end
            .iter()
            .filter_map(|&i| self.series.get(i))
            .map(|s| {
                let r0 = rank_of(&self.series, |x| x.before, &s.id);
                let r1 = rank_of(&self.series, |x| x.after, &s.id);
                format!(
                    "{}: {} to {}, {}, rank {} to {}",
                    s.label,
                    value_text(s.before, &prefix, &suffix),
                    value_text(s.after, &prefix, &suffix),
                    change_text(s.after - s.before, &prefix, &suffix),
                    r0,
                    r1,
                )
            })
            .collect();
        // Per-row paint colours resolved once for the canvas and the labels.
        let row_inks: Vec<Hsla> = (0..self.series.len())
            .map(|i| {
                let focused = active == Some(i);
                let accent = accent_flags.get(i).copied().unwrap_or(false);
                if accent {
                    highlight_color()
                } else if focused {
                    p.ink
                } else {
                    p.ink.opacity(0.36)
                }
            })
            .collect();
        let p_bounds = self.bounds.clone();
        let hover_bounds = self.bounds.clone();
        let touch_bounds = self.bounds.clone();
        let touch_rows = rows.clone();
        let touch_l0 = l0.clone();
        let touch_l1 = l1.clone();
        let ranks_shown = self.ranks;
        let plot_left_labels = l0.clone();
        let plot_right_labels = l1.clone();
        let paint_values = values.clone();
        let paint_inks = row_inks.clone();
        let nearest_at = Rc::new(move |b: Bounds<Pixels>, pos: Point<Pixels>| {
            nearest_series(b, pos, &touch_rows, &touch_l0, &touch_l1, x0, x1)
        });
        let hover_nearest = nearest_at.clone();
        let touch_nearest = nearest_at.clone();
        let touching = self.touching.clone();
        let touch = cx.listener(move |s, e: &TouchDragEvent, _, cx| {
            let index = match e.phase {
                TouchPhase::Ended | TouchPhase::Cancelled => None,
                _ => touch_nearest(touch_bounds.get(), e.position),
            };
            s.inspect(index, cx);
        });
        let plot = div()
            .id("slope-plot")
            .relative()
            .w_full()
            .h(px(plot_height))
            .on_hover(cx.listener(|s, over: &bool, w, cx| {
                if !*over && !w.last_input_was_keyboard() {
                    s.inspect(None, cx);
                }
            }))
            .on_mouse_move(cx.listener(move |s, e: &MouseMoveEvent, _, cx| {
                s.inspect(hover_nearest(hover_bounds.get(), e.position), cx);
            }))
            .child(
                canvas(
                    move |b, w, _| {
                        let previous = p_bounds.get();
                        if previous.size != b.size
                            || intersects_viewport(previous, w.viewport_size())
                                != intersects_viewport(b, w.viewport_size())
                        {
                            w.request_animation_frame();
                        }
                        p_bounds.set(b);
                    },
                    move |b, _, w, _| {
                        let width = f32::from(b.size.width);
                        let height = f32::from(b.size.height);
                        let (x0, x1) = axes(width, ranks_shown);
                        let y_of = |v: f32| PAD + (1. - (v - lo) / span) * (height - PAD * 2.);
                        // Axes sit on whole pixels like the reference's
                        // crispEdges so a 1px rule stays a solid column.
                        for x in [x0, x1] {
                            let col = (b.origin.x + px(x)).round() - px(0.5);
                            let top = b.origin.y.round();
                            let bottom = (b.origin.y + b.size.height).round();
                            w.paint_quad(fill(
                                Bounds::new(point(col, top), size(px(1.), bottom - top)),
                                p.line,
                            ));
                        }
                        for (i, (a, z)) in paint_values.iter().enumerate() {
                            let focused = active == Some(i);
                            let dim = active.is_some_and(|on| on != i);
                            let opacity = if dim { 0.14 } else { 1. };
                            let ink = paint_inks[i];
                            let _ = focused;
                            let at = |x: f32, value: f32| {
                                point(b.origin.x + px(x), b.origin.y + px(y_of(value)))
                            };
                            let left = at(x0, *a);
                            let end = at(x1, *z);
                            // Leader hairlines from each spread label to its dot.
                            let leaders = [
                                (
                                    point(
                                        left.x - px(6.),
                                        b.origin.y
                                            + px(plot_left_labels
                                                .get(i)
                                                .copied()
                                                .unwrap_or(0.)
                                                .clamp(0., height)),
                                    ),
                                    point(left.x - px(1.), left.y),
                                ),
                                (
                                    point(end.x + px(1.), end.y),
                                    point(
                                        end.x + px(6.),
                                        b.origin.y
                                            + px(plot_right_labels
                                                .get(i)
                                                .copied()
                                                .unwrap_or(0.)
                                                .clamp(0., height)),
                                    ),
                                ),
                            ];
                            for (from, to) in leaders {
                                if (f32::from(from.y - to.y)).abs() < 0.75 {
                                    continue;
                                }
                                let mut leader = PathBuilder::stroke(px(1.));
                                leader.move_to(from);
                                leader.line_to(to);
                                if let Ok(path) = leader.build() {
                                    w.paint_path(path, p.line.opacity(opacity));
                                }
                            }
                            // The line draws in from start to end with a small stagger.
                            let delay = 0.1 + i as f32 * 0.05;
                            let progress = in_out(((age - delay) / 0.7).clamp(0., 1.));
                            let tip = point(
                                left.x + (end.x - left.x) * progress,
                                left.y + (end.y - left.y) * progress,
                            );
                            let mut line = PathBuilder::stroke(px(2.));
                            line.move_to(left);
                            line.line_to(tip);
                            if let Ok(path) = line.build() {
                                w.paint_path(path, ink.opacity(opacity));
                            }
                            // Dots arrive with the line: start immediately, end as it lands.
                            for (pt, dot_delay) in
                                [(left, i as f32 * 0.05), (tip, 0.7 + i as f32 * 0.05)]
                            {
                                let scale = if reduced {
                                    1.
                                } else {
                                    ((age - dot_delay) / 0.2).clamp(0., 1.)
                                };
                                if scale <= 0.01 {
                                    continue;
                                }
                                let r = 4. * scale;
                                let ring = r + 2.;
                                w.paint_quad(
                                    fill(
                                        Bounds::new(
                                            point(pt.x - px(ring), pt.y - px(ring)),
                                            size(px(ring * 2.), px(ring * 2.)),
                                        ),
                                        p.panel,
                                    )
                                    .corner_radii(px(ring)),
                                );
                                w.paint_quad(
                                    fill(
                                        Bounds::new(
                                            point(pt.x - px(r), pt.y - px(r)),
                                            size(px(r * 2.), px(r * 2.)),
                                        ),
                                        ink.opacity(opacity),
                                    )
                                    .corner_radii(px(r)),
                                );
                            }
                        }
                    },
                )
                .size_full(),
            )
            .children({
                let mut labels = Vec::new();
                for (i, series) in self.series.iter().enumerate() {
                    let focused = active == Some(i);
                    let accent = accent_flags.get(i).copied().unwrap_or(false);
                    let dim = active.is_some_and(|on| on != i);
                    let opacity = if dim { 0.3 } else { 1. };
                    let narrow = width < 440.;
                    let label_size = if narrow { 12. } else { 14. };
                    let label_gap = if narrow { 6. } else { 8. };
                    let name_color = if focused || accent {
                        p.ink
                    } else {
                        p.secondary
                    };
                    let visual = &self.visual[i];
                    let enter = if reduced {
                        1.
                    } else {
                        ((age - i as f32 * 0.05) / 0.3).clamp(0., 1.)
                    };
                    let step = if reduced {
                        1.
                    } else {
                        ((age - 0.7 - i as f32 * 0.05) / 0.3).clamp(0., 1.)
                    };
                    labels.push(
                        div()
                            .absolute()
                            .left(px(0.))
                            .top(px((l0[i] - 10.).max(0.)))
                            .w(px((x0 - 10.).max(1.)))
                            .h(px(20.))
                            .flex()
                            .items_center()
                            .justify_end()
                            .gap(px(label_gap))
                            .overflow_hidden()
                            .text_size(px(label_size))
                            .line_height(px(20.))
                            .opacity(opacity * enter)
                            .child(
                                div()
                                    .min_w_0()
                                    .overflow_hidden()
                                    .text_ellipsis()
                                    .text_color(name_color)
                                    .child(series.label.clone()),
                            )
                            .child(
                                div()
                                    .flex_none()
                                    .text_color(p.ink)
                                    .font_weight(if accent {
                                        FontWeight::MEDIUM
                                    } else {
                                        FontWeight::NORMAL
                                    })
                                    .child(value_text(series.before, &prefix, &suffix)),
                            ),
                    );
                    // Rank move: an arrow glyph and a number that rolls the way it moved.
                    let move_places = rank_move(&self.series, &series.id);
                    let roll_p = visual.roll_p(cx);
                    let dir: f32 = if visual.roll_from_below { 1. } else { -1. };
                    let new_off = dir * 6. * (1. - roll_p);
                    let old_off = -dir * 6. * roll_p;
                    let rank_color = if move_places > 0 {
                        p.secondary
                    } else {
                        p.faint
                    };
                    let arrow = if move_places > 0 {
                        Some(icon(Glyph::ArrowUp, 8., rank_color).into_any_element())
                    } else if move_places < 0 {
                        Some(
                            transformed(
                                Glyph::ArrowUp,
                                8.,
                                rank_color,
                                std::f32::consts::PI,
                                1.,
                                (0., 0.),
                                1.,
                            )
                            .into_any_element(),
                        )
                    } else {
                        None
                    };
                    let rank_number = div()
                        .relative()
                        .h(px(16.))
                        .min_w(px(12.))
                        .when_some(
                            (!visual.prev_rank.is_empty() && roll_p < 1.).then(|| {
                                div()
                                    .absolute()
                                    .left_0()
                                    .top(px(old_off))
                                    .text_color(rank_color)
                                    .opacity(1. - roll_p)
                                    .child(visual.prev_rank.clone())
                            }),
                            |row, old| row.child(old),
                        )
                        .child(
                            div()
                                .absolute()
                                .left_0()
                                .top(px(new_off))
                                .text_color(rank_color)
                                .opacity(roll_p)
                                .child(visual.rank.clone()),
                        );
                    labels.push(
                        div()
                            .absolute()
                            .left(px(x1 + 10.))
                            .top(px((l1[i] - 10.).max(0.)))
                            .h(px(20.))
                            .flex()
                            .items_center()
                            .gap(px(label_gap))
                            .text_size(px(label_size))
                            .line_height(px(20.))
                            .opacity(opacity * step)
                            .child(
                                div()
                                    .flex_none()
                                    .text_color(p.ink)
                                    .font_weight(if accent {
                                        FontWeight::MEDIUM
                                    } else {
                                        FontWeight::NORMAL
                                    })
                                    .child(value_text(series.after, &prefix, &suffix)),
                            )
                            .when(self.ranks, |row| {
                                row.child(
                                    div()
                                        .min_w(px(30.))
                                        .flex()
                                        .items_center()
                                        .gap(px(2.))
                                        .text_size(px(12.))
                                        .line_height(px(16.))
                                        .when_some(arrow, |rank, glyph| rank.child(glyph))
                                        .child(rank_number),
                                )
                            }),
                    );
                }
                labels
            })
            .child(
                canvas(
                    |b, w, _| w.insert_hitbox(b, HitboxBehavior::Normal),
                    move |_, hit, w, _| {
                        w.on_mouse_event(move |e: &TouchDragEvent, phase, w, cx| {
                            if !phase.bubble() {
                                return;
                            }
                            if e.phase == TouchPhase::Started {
                                touching.set(hit.is_hovered(w));
                            }
                            if !touching.get() {
                                return;
                            }
                            if matches!(e.phase, TouchPhase::Started | TouchPhase::Moved) {
                                touch(e, w, cx);
                            }
                            if matches!(e.phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                                touching.set(false);
                            }
                        });
                    },
                )
                .absolute()
                .inset_0(),
            );
        // The stage carries the column headings, the plot and the tooltip.
        let stage = div()
            .id("slope-stage")
            .relative()
            .w_full()
            .role(Role::Group)
            .tab_index(if empty { -1 } else { 0 })
            .aria_label(format!(
                "{}. {}",
                self.label,
                tr(
                    cx,
                    "Use up and down arrows to move between items in end-value order",
                    "使用上下方向键按期末数值顺序在各项目间移动"
                )
            ))
            .on_key_down(cx.listener(|s, e: &KeyDownEvent, w, cx| {
                let n = s.series.len();
                if n == 0 {
                    return;
                }
                let order = end_order(&s.series);
                let at = s
                    .active
                    .and_then(|i| order.iter().position(|&x| x == i))
                    .map(|o| o as isize)
                    .unwrap_or(-1);
                let target = match e.keystroke.key.as_str() {
                    "escape" if s.active.is_some() => None,
                    "down" | "right" => Some((at + 1).clamp(0, n as isize - 1) as usize),
                    "up" | "left" => {
                        Some((if at < 0 { 0 } else { at - 1 }).clamp(0, n as isize - 1) as usize)
                    }
                    "home" => Some(0),
                    "end" => Some(n - 1),
                    _ => return,
                };
                w.prevent_default();
                cx.stop_propagation();
                s.inspect(target.map(|o| order[o.min(n - 1)]), cx);
            }))
            .child(div().relative().h(px(HEAD)).when(!empty, |columns| {
                columns
                    .child(
                        div()
                            .absolute()
                            .left(px((x0 - 40.).max(0.)))
                            .top(px(4.))
                            .w(px(80.))
                            .text_center()
                            .text_size(px(14.))
                            .line_height(px(20.))
                            .text_color(p.faint)
                            .child(self.start_label.clone()),
                    )
                    .child(
                        div()
                            .absolute()
                            .left(px((x1 - 40.).max(0.)))
                            .top(px(4.))
                            .w(px(80.))
                            .text_center()
                            .text_size(px(14.))
                            .line_height(px(20.))
                            .text_color(p.faint)
                            .child(self.end_label.clone()),
                    )
            }))
            .child(if empty {
                div()
                    .flex()
                    .items_center()
                    .justify_center()
                    .min_h(px(160.))
                    .text_size(px(14.))
                    .line_height(px(20.))
                    .text_color(p.faint)
                    .child(self.empty_label.clone())
                    .into_any_element()
            } else {
                plot.into_any_element()
            })
            .when_some(
                self.tip_shown
                    .filter(|_| !empty)
                    .and_then(|i| self.series.get(i).cloned())
                    .map(|series| {
                        let r0 = rank_of(&self.series, |x| x.before, &series.id);
                        let r1 = rank_of(&self.series, |x| x.after, &series.id);
                        (series, r0, r1)
                    })
                    .filter(|_| tip_opacity > 0.01),
                |stage, (series, r0, r1)| {
                    stage.child(
                        div()
                            .absolute()
                            .left(px(tip_left))
                            .top(px(tip_top))
                            .min_w(px(168.))
                            .max_w(px(240.))
                            .px(px(12.))
                            .py(px(10.))
                            .rounded(px(14.))
                            .bg(p.tray)
                            .border_1()
                            .border_color(p.line)
                            .shadow_lg()
                            .flex()
                            .flex_col()
                            .gap(px(3.))
                            .opacity(tip_opacity)
                            .child(
                                div()
                                    .mb(px(2.))
                                    .text_size(px(14.))
                                    .line_height(px(20.))
                                    .font_weight(FontWeight::MEDIUM)
                                    .text_color(p.ink)
                                    .child(series.label.clone()),
                            )
                            .child(
                                div()
                                    .flex()
                                    .justify_between()
                                    .gap(px(12.))
                                    .text_size(px(14.))
                                    .line_height(px(18.))
                                    .child(
                                        div()
                                            .text_color(p.secondary)
                                            .child(self.start_label.clone()),
                                    )
                                    .child(
                                        div()
                                            .font_weight(FontWeight::MEDIUM)
                                            .text_color(p.ink)
                                            .child(value_text(series.before, &prefix, &suffix)),
                                    ),
                            )
                            .child(
                                div()
                                    .flex()
                                    .justify_between()
                                    .gap(px(12.))
                                    .text_size(px(14.))
                                    .line_height(px(18.))
                                    .child(
                                        div().text_color(p.secondary).child(self.end_label.clone()),
                                    )
                                    .child(
                                        div()
                                            .font_weight(FontWeight::MEDIUM)
                                            .text_color(p.ink)
                                            .child(value_text(series.after, &prefix, &suffix)),
                                    ),
                            )
                            .child(
                                div()
                                    .mt(px(2.))
                                    .text_size(px(12.))
                                    .line_height(px(20.))
                                    .text_color(p.faint)
                                    .child(format!(
                                        "{}, {}",
                                        change_text(series.after - series.before, &prefix, &suffix),
                                        rank_line(r0, r1),
                                    )),
                            ),
                    )
                },
            );
        let readings = div()
            .absolute()
            .size_1()
            .overflow_hidden()
            .child(div().id("slope-live").role(Role::Row).aria_label(announce))
            .child(
                div()
                    .id("slope-summary")
                    .role(Role::Row)
                    .aria_label(summary),
            )
            .child(div().id("slope-table").role(Role::Table).children(
                table_rows.into_iter().enumerate().map(|(i, row)| {
                    div()
                        .id(("slope-reading", i))
                        .role(Role::Row)
                        .aria_label(row)
                }),
            ));
        let narrow_card = width > 0. && width < 420.;
        column()
            .w(px(720.))
            .max_w_full()
            .gap(px(20.))
            .p(px(if narrow_card { 16. } else { 24. }))
            .rounded(crate::foundation::surface_radius(cx))
            .bg(p.panel)
            .border_1()
            .border_color(p.line)
            .text_color(p.ink)
            .child(
                column()
                    .gap(px(2.))
                    .child(title(self.label.clone(), p))
                    .when_some(self.meta.clone(), |heading, meta| {
                        heading.child(
                            div()
                                .text_size(px(13.))
                                .line_height(px(18.))
                                .text_color(p.faint)
                                .child(meta),
                        )
                    }),
            )
            .child(
                div()
                    .id("slope-figure")
                    .role(Role::Figure)
                    .w_full()
                    .aria_label(self.label.clone())
                    .child(stage),
            )
            .child(readings)
    }
}

#[cfg(test)]
mod tests {
    use super::{
        SlopeChart, SlopeSeries, axes, change_text, end_order, grouped1, nearest_series, rank_move,
        spread_labels, tip_anchor, value_text,
    };
    use gpui::{Bounds, TestAppContext, point, px};

    #[test]
    fn spread_forms_one_group_centred_on_its_members() {
        // Touching labels merge into one group: (50 + 30 + 11) / 3 = 30.3.
        let out = spread_labels(&[50., 50., 51.], 200.);
        assert!((out[0] - 30.33).abs() < 0.5, "{out:?}");
        assert!((out[1] - 50.33).abs() < 0.5, "{out:?}");
        assert!((out[2] - 70.33).abs() < 0.5, "{out:?}");
        // Far-apart labels stay where they want to be.
        assert_eq!(
            spread_labels(&[10., 100., 190.], 200.),
            vec![10., 100., 190.]
        );
        assert!(spread_labels(&[], 200.).is_empty());
    }
    #[test]
    fn grouped_values_drop_the_trailing_zero() {
        assert_eq!(grouped1(4.0), "4");
        assert_eq!(grouped1(3.1), "3.1");
        assert_eq!(grouped1(0.05), "0.1");
        assert_eq!(value_text(3.1, "", "%"), "3.1%");
        assert_eq!(change_text(1.5, "", "%"), "+1.5%");
        assert_eq!(change_text(-0.6, "", "%"), "\u{2212}0.6%");
    }
    #[test]
    fn end_order_and_rank_moves_read_largest_first() {
        let series = vec![
            SlopeSeries::new("email", "Email", 3.1, 4.6),
            SlopeSeries::new("search", "Search", 3.4, 3.6),
            SlopeSeries::new("social", "Social", 1.9, 1.3),
        ];
        assert_eq!(end_order(&series), vec![0, 1, 2]);
        assert_eq!(rank_move(&series, &"email".into()), 1);
        assert_eq!(rank_move(&series, &"social".into()), 0);
        // A dataset where social overtakes search by end value.
        let flipped = vec![
            SlopeSeries::new("email", "Email", 3.1, 3.2),
            SlopeSeries::new("search", "Search", 3.4, 1.0),
            SlopeSeries::new("social", "Social", 1.9, 4.0),
        ];
        assert_eq!(end_order(&flipped), vec![2, 0, 1]);
        assert_eq!(rank_move(&flipped, &"social".into()), 2);
    }
    #[test]
    fn nearest_reads_labels_beside_their_column() {
        let bounds = Bounds {
            origin: point(px(0.), px(0.)),
            size: gpui::size(px(720.), px(200.)),
        };
        let rows = vec![(50., 40.), (150., 160.)];
        let l0 = vec![50., 150.];
        let l1 = vec![40., 160.];
        let (x0, x1) = (168., 624.);
        // Inside the plot the line nearest the pointer wins.
        assert_eq!(
            nearest_series(bounds, point(px(396.), px(45.)), &rows, &l0, &l1, x0, x1),
            Some(0)
        );
        // Left of the first axis reads the spread start label.
        assert_eq!(
            nearest_series(bounds, point(px(20.), px(58.)), &rows, &l0, &l1, x0, x1),
            Some(0)
        );
        // Right of the last axis reads the spread end label.
        assert_eq!(
            nearest_series(bounds, point(px(700.), px(155.)), &rows, &l0, &l1, x0, x1),
            Some(1)
        );
        // Far away reads nothing.
        assert_eq!(
            nearest_series(bounds, point(px(396.), px(200.)), &rows, &l0, &l1, x0, x1),
            None
        );
    }
    #[test]
    fn tooltip_stays_above_when_it_fits_and_below_when_it_does_not() {
        let (left, top) = tip_anchor(150., 200., 720., 168., 624.);
        assert!((left - (396. - 90.)).abs() < 0.5, "{left}");
        assert!((top - (28. + 150. - 104. - 16.)).abs() < 0.5, "{top}");
        let (_, low) = tip_anchor(10., 200., 720., 168., 624.);
        assert!((low - (28. + 10. + 16.)).abs() < 0.5, "{low}");
    }
    #[test]
    fn axes_keep_the_plot_between_the_label_rooms() {
        // Wide card: 168 in from the left, 96 in from the right of 670.
        assert_eq!(axes(670., true), (168., 574.));
        assert_eq!(axes(670., false), (168., 606.));
        // Narrow stages shrink the rooms instead of crossing the axes.
        assert_eq!(axes(380., true), (132., 304.));
        assert_eq!(axes(150., true), (116., 156.));
    }
    #[test]
    fn plot_canvas_spans_the_full_card_width() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let series = vec![
            SlopeSeries::new("email", "Email", 3.1, 4.6),
            SlopeSeries::new("search", "Search", 3.4, 3.6),
            SlopeSeries::new("social", "Social", 1.9, 1.3),
            SlopeSeries::new("referral", "Referral", 2.2, 3.9),
        ];
        let (view, w) = app.add_window_view(|_, _| {
            SlopeChart::new("Conversion", series)
                .with_start_label("Q1")
                .with_end_label("Q2")
                .with_highlight("email")
        });
        w.run_until_parked();
        w.update(|_, cx| {
            let chart = view.read(cx);
            let b = chart.bounds.get();
            assert!(
                (b.size.width - px(670.)).abs() < px(2.),
                "plot canvas is {:?} wide, want 670",
                b.size.width
            );
        });
    }
    #[test]
    fn switching_datasets_slides_values_without_jumping() {
        use std::time::Duration;
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (view, w) = app.add_window_view(|_, _| {
            SlopeChart::new(
                "Conversion",
                vec![SlopeSeries::new("email", "Email", 3.1, 4.6)],
            )
        });
        w.run_until_parked();
        let samples = w.update(|_, cx| {
            let t0 = cx.background_executor().now();
            view.update(cx, |chart, cx| {
                chart.set_series(vec![SlopeSeries::new("email", "Email", 3.6, 5.2)], cx);
                (0..=5)
                    .map(|step| {
                        let at = t0 + Duration::from_millis(step * 120);
                        let (before, _) = chart.visual[0].before.sample_batch(at, false);
                        let (after, _) = chart.visual[0].after.sample_batch(at, false);
                        (before, after)
                    })
                    .collect::<Vec<_>>()
            })
        });
        // The first sample after the switch reads the old endpoints: motion
        // starts where the line was drawn, never from a reset position.
        assert!(
            (samples[0].0 - 3.1).abs() < 0.05 && (samples[0].1 - 4.6).abs() < 0.05,
            "first sample {samples:?}"
        );
        for (a, b) in samples.iter().zip(samples.iter().skip(1)) {
            assert!(
                b.0 >= a.0 - 0.02 && b.1 >= a.1 - 0.02,
                "monotone {samples:?}"
            );
        }
        assert!(
            (samples[5].0 - 3.6).abs() < 0.05 && (samples[5].1 - 5.2).abs() < 0.05,
            "settles at the new values {samples:?}"
        );
        let mid = samples[2].0;
        assert!(
            (3.15..3.55).contains(&mid),
            "mid-frame inside the slide: {mid}"
        );
    }
    #[test]
    fn switching_datasets_keeps_focus_when_the_key_survives() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (view, w) = app.add_window_view(|_, _| {
            SlopeChart::new(
                "Conversion",
                vec![SlopeSeries::new("email", "Email", 3.1, 4.6)],
            )
        });
        w.run_until_parked();
        w.update(|_, cx| {
            view.update(cx, |chart, cx| {
                chart.inspect(Some(0), cx);
                chart.set_series(vec![SlopeSeries::new("email", "Email", 3.6, 5.2)], cx);
            });
        });
        w.run_until_parked();
        w.update(|_, cx| {
            let chart = view.read(cx);
            assert_eq!(chart.active, Some(0), "a surviving key keeps its focus");
            assert_eq!(chart.visual[0].id, "email");
        });
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

